<template>
  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('infor_tenant_id') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-input
        class="s-field back-white min-width-700px"
        outlined
        dense
        v-model="existing_tenant_id"
      />
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('upload_file') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-file
        class="s-field back-white"
        style="min-width: 250px;"
        outlined
        dense
        counter
        multiple
        v-model="file"
        :label="$t('import_type')"
      >
        <template v-slot:prepend>
          <q-icon name="attach_file" />
        </template>
      </q-file>
    </div>
  </div>

  <div class="settings-toggle-item" v-if="exiting_metadate_url">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('existing_upload_file') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-input
        class="s-field back-white min-width-700px"
        outlined
        dense
        v-model="exiting_metadate_url"
        readonly
      />
      <f-btn
        @click="downloadMetadata"
      >
        <Icon icon="mdi:download" width="20" height="20" />
        <q-tooltip>{{ $t('export_type') }}</q-tooltip>
      </f-btn>
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label"></span>
    </div>
    <div class="settings-toggle-actions">
      <f-btn
        :label="$t('configure_save_button')"
        @click="saveConfiguration"
      />
      <f-btn
        v-if="exiting_metadate_url"
        :label="$t('delete')"
        @click="deleteConfig"
      />
    </div>
  </div>

  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import axios from 'axios';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { api, getAuthorizationToken } from 'pages/APIs';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { samlConfigApiService } from 'src/services';
import {
  getOrgId,
  addOrgIdQueryString,
} from 'src/utils/organization/org_id_helper';

export default defineComponent({
  el: '#app',
  
  mixins: [helperMixin],
  data() {
    return {};
  },
  mounted: function () {
    this.init();
  },
  methods: {
    async init() {
      try {
        this.loading = true;
        let token: string = await getAuthorizationToken();
        await this.fetchMetaDataInfo(token);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async fetchMetaDataInfo(token: any) {
      let response = await axios.get(addOrgIdQueryString(api.fetch_saml_meta), {
        headers: {
          Authorization: token,
        },
      });

      const tennant_id = response.data.tennant_id;
      if (tennant_id && tennant_id !== 'undefined') {
        this.existing_tenant_id = tennant_id;
      }

      const exiting_metadate_url = response.data.saml_download_path;
      if (exiting_metadate_url && exiting_metadate_url !== 'undefined') {
        this.exiting_metadate_url = exiting_metadate_url || '';
      }
    },

    openFileExplorer() {
      const file_upload = document.getElementById('uploadfile') as HTMLElement;
      if (file_upload) {
        file_upload.click();
      }
    },

    saveConfiguration() {
      if (!this.file) {
        notify.error(this.$t('NO_FILE_SELECTED'));
        return;
      }
      this.uploadFile(this.file[0]);
    },

    async downloadMetadata() {
      try {
        this.loading = true;
        let token: string = await getAuthorizationToken();
        let response = await axios.get(
          addOrgIdQueryString(this.exiting_metadate_url),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        this.decodeRequest(response.data);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async uploadFile(file: File) {
      try {
        if (file.type !== 'text/xml') {
          notify.error(this.$t('ONLY_XML_ALLOWED'));
          return;
        }

        this.loading = true;
        let formData = new FormData();
        formData.append('file', file);
        formData.append('tenant_id', this.infor_tenant_id);
        formData.append('org_id', getOrgId());
        let token: string = await getAuthorizationToken();
        await axios.post(api.save_saml_configurations, formData, {
          headers: {
            'Content-Type': 'multipart/form-data',
            Authorization: token,
          },
        });

        await this.init();
        this.file = null;
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    decodeRequest(file: any) {
      var filename = 'configured_metadata.xml';
      var pom = document.createElement('a');
      var bb = new Blob([file], { type: 'text/xml' });
      pom.setAttribute('href', window.URL.createObjectURL(bb));
      pom.setAttribute('download', filename);
      pom.dataset.downloadurl = ['text/xml', pom.download, pom.href].join(':');
      pom.draggable = true;
      pom.classList.add('dragout');
      pom.click();
    },

    async deleteConfig() {
      try {
        this.loading = true;
        await samlConfigApiService.delete();
        this.resetViewData();
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    resetViewData() {
      this.infor_tenant_id = '';
      this.exiting_metadate_url = '';
      this.existing_tenant_id = '';
      this.file = null;
    },
  },
  setup() {
    return {
      loading: ref(false),
      infor_tenant_id: ref(''),
      existing_tenant_id: ref(''),
      exiting_metadate_url: ref(''),
      file: ref(null as any),
    };
  },
});
</script>
