<template>
    <!-- Header Section -->
    <div class="row items-center justify-between q-mb-lg">
      <div>
        <div class="text-subtitle1 text-weight-bold">{{ $t('api_keys') }}</div>
        <div class="text-caption text-grey-7">
          {{ $t('api_keys_description') }}
        </div>
      </div>
      <q-btn
        color="primary"
        icon="add"
        :label="$t('create_api_key')"
        @click="showCreateDialog = true"
        unelevated
        no-caps
      />
    </div>

    <!-- API Keys Table using DocBitsTable -->
    <q-card flat bordered class="api-keys-card">
      <DocBitsTable
        :rows="apiKeys"
        :columns="columns"
        row-key="id"
        :loading="loading"
        table-id="api-keys-table"
        :no-data-label="noApiKeysLabel"
        :features="tableFeatures"
        :row-actions="rowActions"
        :pagination="tablePagination"
        table-class="api-keys-table"
        @row-action="handleRowAction"
      >
        <!-- Key Prefix Column -->
        <template #body-cell-key_prefix="{ row }">
          <div class="row items-center no-wrap">
            <code class="key-prefix q-px-sm q-py-xs rounded-borders">
              {{ row.key_prefix }}****
            </code>
            <q-btn
              flat
              dense
              round
              icon="content_copy"
              size="sm"
              color="grey-7"
              @click.stop="copyText(row.key_prefix)"
              class="q-ml-xs"
            >
              <q-tooltip>{{ $t('copy_prefix') }}</q-tooltip>
            </q-btn>
          </div>
        </template>

        <!-- Name Column -->
        <template #body-cell-name="{ row }">
          <div class="text-weight-medium">{{ row.name || '-' }}</div>
          <div v-if="row.description" class="text-caption text-grey-6">
            {{ row.description }}
          </div>
        </template>

        <!-- Expires Column -->
        <template #body-cell-expires_at="{ row }">
          <template v-if="!row.expires_at">
            <q-chip dense color="grey-3" text-color="grey-8" size="sm">
              {{ $t('never') }}
            </q-chip>
          </template>
          <template v-else-if="isExpired(row.expires_at)">
            <q-chip dense color="negative" text-color="white" size="sm" icon="warning">
              {{ $t('expired') }}
            </q-chip>
          </template>
          <template v-else>
            {{ formatDate(row.expires_at) }}
          </template>
        </template>

        <!-- Last Used Column -->
        <template #body-cell-last_used_at="{ row }">
          <template v-if="row.last_used_at">
            {{ formatRelativeTime(row.last_used_at) }}
          </template>
          <template v-else>
            <span class="text-grey-5">{{ $t('never_used') }}</span>
          </template>
        </template>

        <!-- Status Column -->
        <template #body-cell-is_active="{ row }">
          <q-chip
            dense
            :color="getStatusColor(row)"
            :text-color="getStatusTextColor(row)"
            size="sm"
          >
            {{ getStatusLabel(row) }}
          </q-chip>
        </template>
      </DocBitsTable>
    </q-card>

    <!-- Create API Key Dialog -->
    <q-dialog v-model="showCreateDialog" persistent>
      <q-card style="min-width: 450px">
        <q-card-section class="row items-center q-pb-none">
          <div class="text-h6">{{ $t('create_api_key') }}</div>
          <q-space />
          <q-btn icon="close" flat round dense v-close-popup />
        </q-card-section>

        <q-card-section>
          <q-form @submit.prevent="createKey" class="q-gutter-md">
            <q-input
              v-model="newKeyForm.name"
              :label="$t('key_name')"
              outlined
              :rules="[val => !!val || $t('name_required')]"
              autofocus
            >
              <template v-slot:hint>
                {{ $t('key_name_hint') }}
              </template>
            </q-input>

            <q-input
              v-model="newKeyForm.description"
              :label="$t('description')"
              outlined
              type="textarea"
              rows="2"
            />

            <q-select
              v-model="newKeyForm.expiration"
              :label="$t('expiration')"
              outlined
              :options="expirationOptions"
              emit-value
              map-options
            />

            <q-input
              v-if="newKeyForm.expiration === 'custom'"
              v-model="newKeyForm.customExpiration"
              :label="$t('custom_expiration_date')"
              outlined
              type="date"
              :min="minDate"
            />
          </q-form>
        </q-card-section>

        <q-card-actions align="right" class="q-pa-md">
          <q-btn
            flat
            :label="$t('cancel')"
            v-close-popup
            no-caps
          />
          <q-btn
            color="primary"
            :label="$t('create')"
            @click="createKey"
            :loading="creating"
            :disable="!newKeyForm.name"
            unelevated
            no-caps
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Edit API Key Dialog -->
    <q-dialog v-model="showEditDialog" persistent>
      <q-card style="min-width: 450px">
        <q-card-section class="row items-center q-pb-none">
          <div class="text-h6">{{ $t('edit_api_key') }}</div>
          <q-space />
          <q-btn icon="close" flat round dense v-close-popup />
        </q-card-section>

        <q-card-section>
          <q-form @submit.prevent="updateKey" class="q-gutter-md">
            <q-input
              v-model="editKeyForm.name"
              :label="$t('key_name')"
              outlined
              :rules="[val => !!val || $t('name_required')]"
              autofocus
            />

            <q-input
              v-model="editKeyForm.description"
              :label="$t('description')"
              outlined
              type="textarea"
              rows="2"
            />
          </q-form>
        </q-card-section>

        <q-card-actions align="right" class="q-pa-md">
          <q-btn
            flat
            :label="$t('cancel')"
            v-close-popup
            no-caps
          />
          <q-btn
            color="primary"
            :label="$t('save')"
            @click="updateKey"
            :loading="updating"
            :disable="!editKeyForm.name"
            unelevated
            no-caps
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Key Created Dialog (Shows Full Key ONCE) -->
    <q-dialog v-model="showKeyCreatedDialog" persistent>
      <q-card style="min-width: 500px">
        <q-card-section class="bg-positive text-white">
          <div class="row items-center">
            <q-icon name="check_circle" size="24px" class="q-mr-sm" />
            <div class="text-h6">{{ $t('api_key_created') }}</div>
          </div>
        </q-card-section>

        <q-card-section>
          <q-banner class="bg-warning-1 text-warning-9 q-mb-md" rounded>
            <template v-slot:avatar>
              <q-icon name="warning" color="warning" />
            </template>
            <strong>{{ $t('key_warning_title') }}</strong>
            <br />
            {{ $t('key_warning_message') }}
          </q-banner>

          <div class="q-mb-md">
            <div class="text-caption text-grey-7 q-mb-xs">{{ $t('your_api_key') }}</div>
            <div class="key-display bg-grey-2 q-pa-md rounded-borders row items-center">
              <code class="col text-body1" style="word-break: break-all;">
                {{ createdKey }}
              </code>
              <q-btn
                flat
                dense
                icon="content_copy"
                color="primary"
                @click="copyCreatedKey"
                class="q-ml-sm"
              >
                <q-tooltip>{{ $t('copy_key') }}</q-tooltip>
              </q-btn>
            </div>
          </div>

          <q-checkbox
            v-model="keyCopiedConfirm"
            :label="$t('key_copied_confirmation')"
          />
        </q-card-section>

        <q-card-actions align="right" class="q-pa-md">
          <q-btn
            color="primary"
            :label="$t('done')"
            @click="closeKeyCreatedDialog"
            :disable="!keyCopiedConfirm"
            unelevated
            no-caps
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Revoke Confirmation Dialog -->
    <q-dialog v-model="showRevokeDialog">
      <q-card style="min-width: 400px">
        <q-card-section class="row items-center">
          <q-icon name="warning" color="negative" size="32px" class="q-mr-md" />
          <div>
            <div class="text-h6">{{ $t('revoke_api_key') }}</div>
            <div class="text-body2 text-grey-7">
              {{ $t('revoke_confirmation', { name: keyToRevoke?.name || keyToRevoke?.key_prefix }) }}
            </div>
          </div>
        </q-card-section>

        <q-card-section>
          <q-banner class="bg-negative-1 text-negative" rounded dense>
            {{ $t('revoke_warning') }}
          </q-banner>
        </q-card-section>

        <q-card-actions align="right" class="q-pa-md">
          <q-btn
            flat
            :label="$t('cancel')"
            v-close-popup
            no-caps
          />
          <q-btn
            color="negative"
            :label="$t('revoke')"
            @click="revokeKey"
            :loading="revoking"
            unelevated
            no-caps
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Delete Confirmation Dialog (for revoked keys) -->
    <q-dialog v-model="showDeleteDialog">
      <q-card style="min-width: 400px">
        <q-card-section class="row items-center">
          <q-icon name="delete_forever" color="negative" size="32px" class="q-mr-md" />
          <div>
            <div class="text-h6">{{ $t('delete_api_key') }}</div>
            <div class="text-body2 text-grey-7">
              {{ $t('delete_key_confirmation', { name: keyToDelete?.name || keyToDelete?.key_prefix }) }}
            </div>
          </div>
        </q-card-section>

        <q-card-section>
          <q-banner class="bg-negative-1 text-negative" rounded dense>
            {{ $t('delete_key_warning') }}
          </q-banner>
        </q-card-section>

        <q-card-actions align="right" class="q-pa-md">
          <q-btn
            flat
            :label="$t('cancel')"
            v-close-popup
            no-caps
          />
          <q-btn
            color="negative"
            :label="$t('delete')"
            @click="deleteKey"
            :loading="deleting"
            unelevated
            no-caps
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref, computed, onMounted } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { userApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import copyUtil from 'src/utils/copyUtil';
import type { UnifiedTableColumn, RowActionItem, TableFeatures } from 'src/components/Table/types/table/unified-table';

export interface ApiKey {
  id: string;
  key_prefix: string;
  name: string | null;
  description: string | null;
  expires_at: string | null;
  last_used_at: string | null;
  is_active: boolean;
  created_at: string;
  revoked_at: string | null;
}

export interface CreateKeyForm {
  name: string;
  description: string;
  expiration: string;
  customExpiration: string;
}

export interface EditKeyForm {
  id: string;
  name: string;
  description: string;
}

export default defineComponent({
  name: 'ApiKeysManager',

  components: {
    DocBitsTable,
  },

  mixins: [copyUtil],

  setup() {
    // Use Tolgee for reactive translations
    // In Options API setup(), useTranslate returns a Ref, so we need to use .value
    const { t: tRef } = useTranslate();
     
    const t = (key: string, params?: any) => tRef.value(key, params);

    // State
    const loading = ref(false);
    const creating = ref(false);
    const updating = ref(false);
    const revoking = ref(false);
    const apiKeys = ref<ApiKey[]>([]);

    // Dialogs
    const showCreateDialog = ref(false);
    const showEditDialog = ref(false);
    const showKeyCreatedDialog = ref(false);
    const showRevokeDialog = ref(false);

    // Form data
    const newKeyForm = ref<CreateKeyForm>({
      name: '',
      description: '',
      expiration: 'never',
      customExpiration: '',
    });

    const editKeyForm = ref<EditKeyForm>({
      id: '',
      name: '',
      description: '',
    });

    const createdKey = ref('');
    const keyCopiedConfirm = ref(false);
    const keyToRevoke = ref<ApiKey | null>(null);
    const keyToDelete = ref<ApiKey | null>(null);
    const showDeleteDialog = ref(false);
    const deleting = ref(false);

    // Table columns for DocBitsTable
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'key_prefix',
        label: t('key'),
        field: 'key_prefix',
        align: 'left',
        sortable: false,
      },
      {
        name: 'name',
        label: t('name'),
        field: 'name',
        align: 'left',
        sortable: true,
      },
      {
        name: 'expires_at',
        label: t('expires'),
        field: 'expires_at',
        align: 'left',
        sortable: true,
      },
      {
        name: 'last_used_at',
        label: t('last_used'),
        field: 'last_used_at',
        align: 'left',
        sortable: true,
      },
      {
        name: 'is_active',
        label: t('status'),
        field: 'is_active',
        align: 'center',
        sortable: true,
      },
    ]);

    // Table features configuration
    const tableFeatures = computed<Partial<TableFeatures>>(() => ({
      sorting: true,
      filtering: false,
      selection: false,
      bulkActions: false,
      rowActions: true,
      resizable: false,
      pagination: true,
      columnReorder: false,
      clientSideSort: true,
      clientSidePagination: true,
    }));

    // Row action items for the action menu
    const rowActions = computed<RowActionItem[]>(() => [
      {
        key: 'edit',
        label: t('edit'),
        icon: 'edit',
        color: 'grey-7',
        show: (row: ApiKey) => row.is_active,
      },
      {
        key: 'revoke',
        label: t('revoke'),
        icon: 'delete',
        color: 'negative',
        separator: true,
        show: (row: ApiKey) => row.is_active,
      },
      {
        key: 'delete',
        label: t('delete'),
        icon: 'delete_forever',
        color: 'negative',
        show: (row: ApiKey) => !row.is_active,  // Only for revoked/inactive keys
      },
    ]);

    // Pagination configuration
    const tablePagination = ref({
      sortBy: null as string | null,
      descending: false,
      page: 1,
      rowsPerPage: 10,
      rowsNumber: 0,
    });

    // No data label
    const noApiKeysLabel = 'no_api_keys';

    // Handle row action from DocBitsTable
    const handleRowAction = (event: { action: string; rowId: string; row: ApiKey }) => {
      if (event.action === 'edit') {
        openEditDialog(event.row);
      } else if (event.action === 'revoke') {
        confirmRevoke(event.row);
      } else if (event.action === 'delete') {
        confirmDelete(event.row);
      }
    };

    // Expiration options
    const expirationOptions = computed(() => [
      { label: t('never_expires'), value: 'never' },
      { label: t('30_days_full'), value: '30' },
      { label: t('90_days_full'), value: '90' },
      { label: t('1_year_full'), value: '365' },
      { label: t('custom'), value: 'custom' },
    ]);

    // Minimum date for custom expiration (tomorrow)
    const minDate = computed(() => {
      const tomorrow = new Date();
      tomorrow.setDate(tomorrow.getDate() + 1);
      return tomorrow.toISOString().split('T')[0];
    });

    // Methods
    const loadApiKeys = async () => {
      loading.value = true;
      try {
        const response = await userApiService.getApiKeys();
        apiKeys.value = response.keys || [];
      } catch (err: any) {
        console.error('Failed to load API keys:', err);
        apiKeys.value = [];
        // Show error for actual failures (not 404 which means no keys exist)
        const status = err?.response?.status || err?.status;
        if (status !== 404) {
          const msg = ApiExceptions.getErrorMessage(err);
          notify.error(
            msg || t('failed_to_load_api_keys', 'Failed to load API keys'),
          );
        }
      } finally {
        loading.value = false;
      }
    };

    const createKey = async () => {
      if (!newKeyForm.value.name) return;

      creating.value = true;
      try {
        let expiresAt: string | null = null;

        if (newKeyForm.value.expiration === 'custom') {
          expiresAt = newKeyForm.value.customExpiration
            ? new Date(newKeyForm.value.customExpiration).toISOString()
            : null;
        } else if (newKeyForm.value.expiration !== 'never') {
          const days = parseInt(newKeyForm.value.expiration);
          const date = new Date();
          date.setDate(date.getDate() + days);
          expiresAt = date.toISOString();
        }

        const response = await userApiService.createApiKey({
          name: newKeyForm.value.name,
          description: newKeyForm.value.description || undefined,
          expires_at: expiresAt,
        });

        // Store the created key to show in dialog
        createdKey.value = response.key;
        keyCopiedConfirm.value = false;

        // Close create dialog, open key created dialog
        showCreateDialog.value = false;
        showKeyCreatedDialog.value = true;

        // Reset form
        newKeyForm.value = {
          name: '',
          description: '',
          expiration: 'never',
          customExpiration: '',
        };

        // Reload the list
        await loadApiKeys();

        notify.success(t('api_key_created_success'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as any);
        notify.error(msg);
        console.error('Failed to create API key:', err);
      } finally {
        creating.value = false;
      }
    };

    const openEditDialog = (key: ApiKey) => {
      editKeyForm.value = {
        id: key.id,
        name: key.name || '',
        description: key.description || '',
      };
      showEditDialog.value = true;
    };

    const updateKey = async () => {
      if (!editKeyForm.value.name) return;

      updating.value = true;
      try {
        await userApiService.updateApiKey(editKeyForm.value.id, {
          name: editKeyForm.value.name,
          description: editKeyForm.value.description || undefined,
        });

        showEditDialog.value = false;
        await loadApiKeys();

        notify.success(t('api_key_updated_success'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as any);
        notify.error(msg);
        console.error('Failed to update API key:', err);
      } finally {
        updating.value = false;
      }
    };

    const confirmRevoke = (key: ApiKey) => {
      keyToRevoke.value = key;
      showRevokeDialog.value = true;
    };

    const revokeKey = async () => {
      if (!keyToRevoke.value) return;

      revoking.value = true;
      try {
        await userApiService.revokeApiKey(keyToRevoke.value.id);

        showRevokeDialog.value = false;
        keyToRevoke.value = null;
        await loadApiKeys();

        notify.success(t('api_key_revoked_success'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as any);
        notify.error(msg);
        console.error('Failed to revoke API key:', err);
      } finally {
        revoking.value = false;
      }
    };

    const confirmDelete = (key: ApiKey) => {
      keyToDelete.value = key;
      showDeleteDialog.value = true;
    };

    const deleteKey = async () => {
      if (!keyToDelete.value) return;

      deleting.value = true;
      try {
        await userApiService.revokeApiKey(keyToDelete.value.id);

        showDeleteDialog.value = false;
        keyToDelete.value = null;
        await loadApiKeys();

        notify.success(t('api_key_deleted_success'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as any);
        notify.error(msg);
        console.error('Failed to delete API key:', err);
      } finally {
        deleting.value = false;
      }
    };

    const closeKeyCreatedDialog = () => {
      showKeyCreatedDialog.value = false;
      createdKey.value = '';
      keyCopiedConfirm.value = false;
    };

    const copyCreatedKey = () => {
      navigator.clipboard.writeText(createdKey.value);
      notify.success(t('key_copied'));
      keyCopiedConfirm.value = true;
    };

    // Helper functions
    const isExpired = (dateStr: string) => {
      return new Date(dateStr) < new Date();
    };

    const formatDate = (dateStr: string) => {
      return new Date(dateStr).toLocaleDateString();
    };

    const formatRelativeTime = (dateStr: string) => {
      const date = new Date(dateStr);
      const now = new Date();
      const diffMs = now.getTime() - date.getTime();
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMs / 3600000);
      const diffDays = Math.floor(diffMs / 86400000);

      if (diffMins < 1) return t('just_now');
      if (diffMins < 60) return t('minutes_ago', { n: diffMins });
      if (diffHours < 24) return t('hours_ago', { n: diffHours });
      if (diffDays < 30) return t('days_ago', { n: diffDays });
      return formatDate(dateStr);
    };

    const getStatusColor = (key: ApiKey) => {
      if (!key.is_active) return 'grey-4';
      if (key.expires_at && isExpired(key.expires_at)) return 'negative';
      return 'positive';
    };

    const getStatusTextColor = (key: ApiKey) => {
      if (!key.is_active) return 'grey-7';
      return 'white';
    };

    const getStatusLabel = (key: ApiKey) => {
      if (!key.is_active) return t('revoked');
      if (key.expires_at && isExpired(key.expires_at)) return t('expired');
      return t('active');
    };

    // Lifecycle
    onMounted(() => {
      loadApiKeys();
    });

    return {
      // State
      loading,
      creating,
      updating,
      revoking,
      deleting,
      apiKeys,
      columns,

      // DocBitsTable configuration
      tableFeatures,
      rowActions,
      tablePagination,
      noApiKeysLabel,
      handleRowAction,

      // Dialogs
      showCreateDialog,
      showEditDialog,
      showKeyCreatedDialog,
      showRevokeDialog,
      showDeleteDialog,

      // Forms
      newKeyForm,
      editKeyForm,
      expirationOptions,
      minDate,
      createdKey,
      keyCopiedConfirm,
      keyToRevoke,
      keyToDelete,

      // Methods
      createKey,
      openEditDialog,
      updateKey,
      confirmRevoke,
      revokeKey,
      confirmDelete,
      deleteKey,
      closeKeyCreatedDialog,
      copyCreatedKey,

      // Helpers
      isExpired,
      formatDate,
      formatRelativeTime,
      getStatusColor,
      getStatusTextColor,
      getStatusLabel,
    };
  },
});
</script>

<style lang="scss" scoped>

