<template>
  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('entity_id') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-input
        class="s-field back-white min-width-700px"
        outlined
        dense
        v-model="entity_id"
        readonly
      />
      <f-btn
        @click="copyText(entity_id)"
      >
        <Icon icon="mdi:content-copy" width="20" height="20" />
        <q-tooltip>{{ $t('copy') }}</q-tooltip>
      </f-btn>
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('slo_url') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-input
        class="s-field back-white min-width-700px"
        outlined
        dense
        v-model="slo_url"
        readonly
      />
      <f-btn
        @click="copyText(slo_url)"
      >
        <Icon icon="mdi:content-copy" width="20" height="20" />
        <q-tooltip>{{ $t('copy') }}</q-tooltip>
      </f-btn>
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('sso_url') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-input
        class="s-field back-white min-width-700px"
        outlined
        dense
        v-model="sso_url"
        readonly
      />
      <f-btn
        @click="copyText(sso_url)"
      >
        <Icon icon="mdi:content-copy" width="20" height="20" />
        <q-tooltip>{{ $t('copy') }}</q-tooltip>
      </f-btn>
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label"></span>
    </div>
    <div class="settings-toggle-actions">
      <f-btn
        @click="downloadInstaller(certificate_url)"
        :label="$t('download_certificate')"
      />
      <f-btn
        @click="downloadInstaller(metadata_url)"
        :label="$t('metadata_url')"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import axios from 'axios';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { api, getAuthorizationToken } from 'pages/APIs';
import copyUtil from 'src/utils/copyUtil';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
  
  mixins: [helperMixin, copyUtil],
  props: ['showSpinner'],

  data() {
    return {
      api_key: '',
      entity_id: '',
      slo_url: '',
      sso_url: '',
      certificate_url: '',
      metadata_url: '',
      file: null as any,
    };
  },

  mounted: function () {
    this.getSAMLInfo();
  },
  setup() {
    return {};
  },

  methods: {
    downloadInstaller(url: any) {
      window.open(url, '_self');
    },
    async getSAMLInfo() {
      this.showLoading();
      try {
        let token: string = await getAuthorizationToken();
        this.fetchConfiguration(token);
        this.hideLoading();
      } catch (err) {
        this.hideLoading();
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async fetchConfiguration(token: any) {
      let response = await axios.get(
        addOrgIdQueryString(api.fetch_saml_configurations),
        {
          headers: {
            Authorization: token,
          },
        },
      );

      this.entity_id = response.data.ENTITY_ID;
      this.sso_url = response.data.SSO;
      this.slo_url = response.data.SLO;
      this.certificate_url = response.data.CERTIFICATE;
      this.metadata_url = response.data.METADATA_URL;
    },
  },
});
</script>

