<template>
  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('org_id') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-input
        class="s-field back-white min-width-700px"
        outlined
        dense
        v-model="org_id"
        readonly
      />
      <f-btn
        @click="copyText(org_id)"
      >
        <Icon icon="mdi:content-copy" width="20" height="20" />
        <q-tooltip>{{ $t('copy') }}</q-tooltip>
      </f-btn>
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('sub_organisation_id') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-input
        class="s-field back-white min-width-700px"
        outlined
        dense
        v-model="sub_org_id"
        readonly
      />
      <f-btn
        :disabled="!sub_org_id"
        @click="copyText(sub_org_id)"
      >
        <Icon icon="mdi:content-copy" width="20" height="20" />
        <q-tooltip>{{ $t('copy') }}</q-tooltip>
      </f-btn>
    </div>
  </div>
</template>

<script lang="ts">

import { defineComponent } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import copyUtil from 'src/utils/copyUtil';
import { useUserStore } from 'src/store/main';
import { getOrgId } from 'src/utils/organization/org_id_helper';

export default defineComponent({
  el: '#app',
  
  mixins: [helperMixin, copyUtil],
  props: ['showSpinner'],

  data() {
    return {
      org_id: getOrgId(),
      sub_org_id: '',
    };
  },
  mounted: async function () {
    await this.fetchSubOrgId();
  },
  setup() {
    const user_store = useUserStore();
    const { getSubOrgId } = user_store;

    return {
      getSubOrgId,
    };
  },
  methods: {
    async fetchSubOrgId() {
      const response = await this.getSubOrgId();
      if (response) {
        this.sub_org_id = response;
      }
    },
  },
});
</script>

<style scoped></style>
